settings.custom_css:
selector .elementor-button{
    position: relative;
    border-radius: 104px;
    background: radial-gradient(51.25% 80.52% at 50.14% 0%, #FDD16E 0%, #F5811E 100%);
    z-index: 1;
    overflow: hidden;
    transition: transform 0.3s ease, filter 0.3s ease, box-shadow 0.3s ease;
}

/* Borda girando */
selector .elementor-button::before{
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 600px;
    height: 600px;
    translate: -50% -50%;
    background: conic-gradient(
        transparent 0deg,
        transparent 60deg,
        #ffd77a 100deg,
        #ffffff 130deg,
        #ffd77a 160deg,
        transparent 200deg,
        transparent 360deg
    );
    animation: btn-spin 2.2s linear infinite;
    z-index: -1;
}

/* Tampa interna (mantém o gradiente) */
selector .elementor-button::after{
    content: "";
    position: absolute;
    inset: 3px;
    border-radius: 104px;
    background: radial-gradient(51.25% 80.52% at 50.14% 0%, #FDD16E 0%, #F5811E 100%);
    z-index: -1;
}

/* Hover */
selector .elementor-button:hover{
    transform: translateY(-2px) scale(1.05);
    filter: brightness(1.1);
    box-shadow:
        0 0 25px rgba(253, 209, 110, 0.7),
        0 0 50px rgba(245, 129, 30, 0.5),
        0 0 12px rgba(255, 255, 255, 0.4) inset;
}

/* acelera a borda no hover */
selector .elementor-button:hover::before{
    animation-duration: 0.9s;
}

/* animação */
@keyframes btn-spin{
    from{
        transform: rotate(0deg);
    }
    to{
        transform: rotate(360deg);
    }
}

selector .elementor-button svg{
    width: 24px; /*altere o tamanho aqui*/
    height: 24px; /*altere o tamanho aqui*/
    vertical-align: middle;
}

selector .elementor-button-content-wrapper {
    align-items: center
}

.botao {
  position: relative;
  z-index: 1;
  border-radius: 12px;

  transition: transform 0.3s ease; /* suaviza o grow */
}

/* efeito grow ao passar o mouse */
.botao:hover {
  transform: scale(1.08);
}

/* halo externo pulsante */
.botao::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: calc(100% + 20px);
  height: calc(100% + 20px);
  background: #FCC86530;
  border-radius: 220px;
  z-index: -1;
  opacity: 0;
  animation: pulseGlow 2.5s ease-in-out infinite;
}

/* animação do brilho */
@keyframes pulseGlow {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1);
  }
  50% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1.05);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1);
  }
}

