.scroll-left,
.scroll-right,
.scroll-bottom,
.scroll-top {
    opacity: 0;
    filter: blur(10px); /* aqui o blur inicial */
    transition: 0.6s all ease;
}

/* Mantém seus transforms separados */
.scroll-left {
    transform: translate3d(-30px, 0, 0);
}

.scroll-right {
    transform: translate3d(30px, 0, 0);
}

.scroll-bottom {
    transform: translate3d(0, 80px, 0);
}

.scroll-top {
    transform: translate3d(0, -80px, 0);
}

/* Estado ativo */
.ativo {
    opacity: 1;
    filter: blur(0); /* remove o blur */
    transform: translate3d(0, 0, 0);
}

page_settings.custom_css:
::selection {
    background-color: rgba(255, 255, 255, 0.125);
}

html, body {
    overflow-x: hidden;
}

p:last-of-type {
    margin-bottom: 0;
}

body::-webkit-scrollbar {
    width: 10px; /* largura da barra de rolagem */
}

body::-webkit-scrollbar-track {
    background-color: #111111; /* cor da área de rastreamento */
}

body::-webkit-scrollbar-thumb {
    background: linear-gradient(90deg, #fff, #fff); /* cor do SCROLL*/
    border-radius: 15px; /* arredondamento do SCROLL */
    border: 2px solid #111111; /* cria espaçamento em torno do SCROLL*/
}



.container {
  position: relative;
  overflow: hidden;
}

.container::before {
  content: "";
  position: absolute;
  top: 70%; /* mantém no fundo */
  left: -300px; /* começa fora da tela */
  width: 1500px;
  height: 600px;
  background: #f6811e;
  border-radius: 50%;
  filter: blur(240px);
opacity: 0.3;
  animation: moveGlow 5s ease-in-out infinite alternate;
}

@keyframes moveGlow {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(calc(100vw + 0px));
  }
}

.float {
  animation: float 3s ease-in-out infinite;
}

@keyframes float {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-15px);
  }
}

.card1 {
  transition: transform 1s cubic-bezier(0.2, 0.8, 0.2, 1),
              box-shadow 0.4s ease;
  transform-style: preserve-3d;
  perspective: 1000px;
  will-change: transform;
}

.card1:hover {
  transform: perspective(1000px)
             translateY(-12px)
             rotateX(3deg)
             rotateY(-4deg)
             scale(1.02);

  box-shadow:
    0 25px 50px rgba(0, 0, 0, 0.15),
    0 10px 20px rgba(0, 0, 0, 0.08);
}
